class Solution {
public:
    long long countPalindromePaths(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; i++) {
            children[parent[i]].push_back(i);
        }
        vector<int> mask(n, 0);
        vector<int> q;
        q.push_back(0);
        for (int i = 0; i < (int)q.size(); i++) {
            int u = q[i];
            for (int v : children[u]) {
                mask[v] = mask[u] ^ (1 << (s[v] - 'a'));
                q.push_back(v);
            }
        }
        unordered_map<int,int> seen;
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int m = mask[i];
            auto it = seen.find(m);
            if (it != seen.end()) ans += it->second;
            for (int c = 0; c < 26; c++) {
                it = seen.find(m ^ (1 << c));
                if (it != seen.end()) ans += it->second;
            }
            seen[m]++;
        }
        return ans;
    }
};
